cat > /tmp/verify_transcript.py <<'PYEOF'
import subprocess, re, collections, pathlib
REPO="/tmp/main-edit"
def gitout(a): return subprocess.run(["git","-C",REPO]+a,capture_output=True,text=True,check=True).stdout
# all friend-message commits across all 6 branches, full history
commits={}
for b in ["rachel","monica","phoebe","joey","chandler","ross"]:
    shas = gitout(["rev-list","origin/friend/"+b]).split()
    for sha in shas:
        body = gitout(["log","-1","--format=%B",sha])
        if re.search(r'^Friend-Message: 1$', body, re.M):
            commits[sha]=(b, body)
# transcript sources
sources=collections.Counter()
paths={}
for p in sorted(pathlib.Path("/tmp/main-edit").glob("S*/E*.md")):
    for m in re.finditer(r'^Source: friend/([a-z]+) @ ([0-9a-f]{40})$', p.read_text(encoding="utf-8"), re.M):
        sources[m.group(2)]+=1
        paths.setdefault(m.group(2),[]).append((p.name, m.group(1)))
missing=[s for s in commits if sources[s]==0]
dupes={s:c for s,c in sources.items() if c>1}
extra=[s for s in sources if s not in commits]
print(f"friend-message commits: {len(commits)}")
print(f"sources in transcript: {sum(sources.values())} unique {len(sources)}")
print(f"MISSING from transcript: {len(missing)}")
for s in missing[:10]: print("  ", s, commits[s][0], gitout(["log","-1","--format=%cI %s",s]).strip())
print(f"DUPLICATES: {len(dupes)}")
for s,c in list(dupes.items())[:10]: print("  ", s, c, paths[s])
print(f"unknown/extra sources: {len(extra)}")
for s in extra[:5]: print("  ", s, paths[s])
PYEOF
python3 /tmp/verify_transcript.py
